// The Muse logo for the sidebar header: the spider silhouette as a mask, painted in the
// text color, so it reads black on the light theme and white on the dark one. The image is
// the product mark from apps/web/public/muse-med-logo.png, cut to its alpha channel.
import { createElement as h } from 'react'

const GLYPH = 'data:image/png;base64,'

/**
 * The bare spider mark.
 * @param {{ size?: number }} props - Edge length in pixels.
 * @returns The mark, hidden from assistive tech (the name beside it is the label).
 */
export function MuseGlyph({ size = 22 }) {
  return h('span', { className: 'bt-muse-glyph', 'aria-hidden': true, style: { width: size, height: size } })
}

export const MUSE_BRAND_CSS = `
.bt-muse-glyph{flex:none;display:inline-block;background:currentColor;-webkit-mask:url(${GLYPH}) center/contain no-repeat;mask:url(${GLYPH}) center/contain no-repeat}
`
